// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 fund) public {
        fund = bound(fund, 0, 1 ether);

        vm.deal(address(this), fund);
        if (fund > 0) {
            (bool s, ) = address(c).call{value: fund}("");
            require(s);
        }

        bool ok;
        vm.deal(caller, 1 wei);
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
